// Anti-aliased bitmap fonts (src/font_data.c, generated by tools/make_fonts.py).
#pragma once

#include <stdint.h>

typedef struct {
    uint32_t offset;        // into the font's bits: rows of 4-bit coverage, two pixels a byte,
                            // each row padded to a whole byte
    uint8_t w, h;           // the bitmap's size
    int8_t x, y;            // its top left from the pen, which sits on the baseline
    uint8_t advance;
} font_glyph_t;

typedef struct {
    const uint8_t *bits;
    const font_glyph_t *glyphs;
    uint8_t first, last;    // the characters it has
    uint8_t ascent, descent, line;
} font_t;

extern const font_t font_small;     // 15 px, labels
extern const font_t font_large;     // 22 px, headings and buttons
